import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system_name = platform.system().lower()
    if "windows" in system_name:
        cmd = ["wmic", "cpu", "get", "loadpercentage", "/value"]
        def get_cpu_usage():
            try:
                output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode(errors="ignore")
                for line in output.splitlines():
                    line = line.strip()
                    if line.lower().startswith("loadpercentage"):
                        parts = line.split("=")
                        if len(parts) == 2:
                            return float(parts[1])
            except Exception:
                pass
            return 0.0
    else:
        cmd = ["top", "-bn1"]
        def get_cpu_usage():
            try:
                output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode(errors="ignore")
                for line in output.splitlines():
                    line_low = line.lower()
                    if "cpu(s)" in line_low or line_low.startswith("%cpu"):
                        tokens = line.replace(",", " ").split()
                        for i, tok in enumerate(tokens):
                            if tok.lower().startswith("%us") or tok.lower().startswith("us,") or tok.lower() == "us":
                                try:
                                    return float(tokens[i - 1])
                                except Exception:
                                    break
                        for t in tokens:
                            try:
                                val = float(t)
                                if 0.0 <= val <= 100.0:
                                    return val
                            except Exception:
                                continue
            except Exception:
                pass
            return 0.0
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time > duration and records:
            break
        timestamp = now
        cpu_usage = get_cpu_usage()
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
        if time.time() - start_time >= duration:
            break
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH
