import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not isinstance(src_folder, str) or not isinstance(dst_folder, str):
        raise TypeError("src_folder and dst_folder must be strings")
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": "Source folder does not exist or is not a directory",
            "failed_files": []
        }
    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception as e:
        return {
            "success": False,
            "message": f"Failed to create destination folder: {e}",
            "failed_files": []
        }
    pattern = os.path.join(src_folder, "*")
    files = [f for f in glob(pattern) if os.path.isfile(f)]
    if not files:
        return {
            "success": True,
            "message": "No files to compress",
            "failed_files": []
        }
    failed_files = []
    for src_file in files:
        filename = os.path.basename(src_file)
        dst_file = os.path.join(dst_folder, filename + ".gz")
        try:
            with open(src_file, "rb") as fin, open(dst_file, "wb") as fout:
                subprocess.Popen(["gzip", "-c"], stdin=fin, stdout=fout)
        except Exception:
            failed_files.append(filename)
    success = len(failed_files) == 0
    if success:
        message = "All files were queued for compression and move successfully"
    else:
        message = "Some files failed to compress or move"
    return {
        "success": success,
        "message": message,
        "failed_files": failed_files
    }
